import numpy as np
import matplotlib.pyplot as plt

sar = (plt.imread('/inputs/sar-echo-tile.png') * 255).astype(np.float64)
woda_I = sar[20:80, 10:70] ** 2

def enl(patch):
    I = np.asarray(patch, dtype=float)
    return float(I.mean() ** 2 / I.var())

def multilook(img, looks):
    img = np.asarray(img, dtype=np.float64)
    if looks <= 1:
        return img.copy()
    h = (img.shape[0] // looks) * looks
    w = (img.shape[1] // looks) * looks
    return img[:h, :w].reshape(h // looks, looks, w // looks, looks).mean(axis=(1, 3))

# Zmieniaj liczbe lookow i obserwuj, jak ENL rosnie, a obraz sie kurczy.
for looks in (1, 2, 3, 5, 8):
    out = multilook(woda_I, looks)
    print('looki', looks, '| ENL', round(enl(out), 1), '| ksztalt', out.shape)
